  const pref = (id, title, body) => `<div class="app notp">${topbar('Settings', 'Saved automatically', btn('Close', { k: 'g', go: 'home' }))}${rail(HOME, 'prefs')}<main class="main" id="m"><div class="tabs">${PREF.map(p => `<a href="#prefs-${p[0]}" data-go="prefs-${p[0]}" class="${p[0] === id ? 'on' : ''}">${p[1]}</a>`).join('')}</div><div class="pg in" style="max-width:${id === 'themes' || id === 'fonts' ? 1320 : 860}px"><h1 class="h1">${title}</h1>${body}</div></main></div>`;
  reg('prefs-themes', 'Settings', 'Themes', () => pref('themes', 'Pick a ground.', `<p class="lede" style="margin-top:-8px">Thirteen themes, one for each effect on the wall. Click one and it spreads across the app. Your choice stays on this device.</p><div class="g3">${THEMES.map(t => fxc(t[0], t[4], t[5], t[1], t[6], { btn: `data-set-theme="${t[0]}" aria-pressed="false"` })).join('')}</div>`));
  reg('prefs-fonts', 'Settings', 'Fonts', () => pref('fonts', 'Pick a voice.', `<p class="lede" style="margin-top:-8px">Six fonts, all built in, so they work offline. Click one and the whole app changes. Numbers and small labels stay in Geist Mono. Your choice stays on this device.</p><div class="g3">${FONTS.map((f, i) => `<button type="button" class="ftc ft-${f[0]}" data-set-font="${f[0]}" aria-pressed="false"><span class="meta"><span>${f[1]}</span><span>${i ? '' : 'Default'}</span></span><span class="word">Sound, in flux.</span><span class="say">${f[2]} Cut it, spin it, pull the vocal out.</span></button>`).join('')}</div>`));
  reg('prefs-general', 'Settings', 'General', () => pref('general', 'General', `<div class="box col"><div class="between"><div class="col" style="gap:2px"><b>Theme</b><span class="lab" data-theme-name></span></div>${btn('Change theme', { go: 'prefs-themes' })}</div><div class="between"><div class="col" style="gap:2px"><b>Font</b><span class="lab" data-font-name></span></div>${btn('Change font', { go: 'prefs-fonts' })}</div>${fld('Language', sel(['English', 'Hindi', 'Español', 'Français', 'Deutsch', 'Português', '日本語']))}${fld('Starting mode', seg(['Simple', 'Pro'], 1))}</div><div class="box col">${tg('Automatic micro-fades on every cut', true, 'Stops clicks. 3 ms by default')}${tg('Snap to zero crossings', true)}${fld('New project sample rate', sel(['48 kHz', '44.1 kHz', '96 kHz']))}</div>`));
  reg('prefs-audio', 'Settings', 'Audio', () => pref('audio', 'Audio', `<div class="box col">${fld('Output', sel(['System default', 'Studio Headphones', 'Laptop speakers']))}${fld('Microphone', sel(['Studio Mic USB', 'Laptop mic']))}<div class="between"><span class="dim">Device runs at 44.1 kHz, project at 48 kHz.</span>${pill('Resampled at output')}</div></div><div class="box col">${fld('Quality', seg(['Best', 'Balanced', 'Battery saver']))}${tg('Lower quality automatically if audio glitches', true)}<div class="between"><span class="dim">Glitches this session</span><span class="mono">0</span></div></div>${sec('Hearing safety', `<div class="box col">${tg('Soft start when playback begins', true)}${tg('Output limiter', true, 'Catches sudden loud peaks')}${tg('Warn about very loud exports', true)}</div>`)}${btn('Run headphone check', { i: 'head', go: 'hpcheck' })}`));
