  reg('prefs-privacy', 'Settings', 'Privacy', () => pref('privacy', 'Privacy', `${cal('lock', '<b>Nothing leaves this device right now.</b> 0 bytes uploaded this session.', 'ac')}<div class="box col"><b>Cloud, per feature</b>${tg('Stems: Best quality', false)}${tg('Text to speech: higher quality voices', false)}${tg('Dubbing', false, 'Required for this feature')}</div><div class="box col">${tg('Crash reports', false, 'Never includes audio, transcripts or file names')}${tg('Usage statistics', false)}</div><div class="row">${btn('Delete all my cloud data', { k: 'dng' })}${btn('See what is stored', { k: 'g' })}</div>`));
  reg('prefs-models', 'Settings', 'AI models', () => pref('models', 'AI models', `<div class="between"><span class="dim">Downloaded once and then work offline.</span><b class="mono">1.2 GB used</b></div><div class="lst box">${[['Stems: Balanced', '820 MB', 1], ['Voice cleanup', '64 MB', 1], ['Transcript: Whisper small', '240 MB', 1], ['Tempo and key', '18 MB', 1], ['Stems: Best', '1.9 GB', 0], ['Transcript: Whisper medium', '780 MB', 0], ['Speech voices (English)', '310 MB', 0]].map(r => `<div><div class="ti"><b>${r[0]}</b><span>${r[1]}${r[2] ? ', verified' : ''}</span></div>${r[2] ? btn('Remove', { k: 'g' }) : btn('Download', { i: 'exp' })}</div>`).join('')}</div>${cal('chip', 'This device: WebGPU, 8 GB of graphics memory. All models will run.')}`));
