  reg('prefs-access', 'Settings', 'Accessibility', () => pref('access', 'Accessibility', `<div class="box col">${tg('Reduce motion', false, 'Follows your system setting')}${tg('High contrast', false)}${tg('Color-blind safe track colors', false)}${sl('Text size', 40, '100%')}</div><div class="box col">${tg('Describe waveforms for screen readers', true, 'For example: loud for 10 seconds, then quiet')}${tg('Announce playback position', false)}${fld('Announcement rate', seg(['Low', 'Medium', 'High']))}</div>${btn('See keyboard commands', { i: 'keys', go: 'prefs-keys' })}`));
  reg('prefs-account', 'Settings', 'Account', () => pref('account', 'Account', `${cal('info', 'You don\'t need an account. Everything on your device works without one. Sign in only for cloud features or a paid plan.')}<div class="box col"><b>Not signed in</b><div class="row">${btn('Sign in', { k: 'p' })}${btn('Create account')}</div></div><div class="box col"><div class="between"><b>Plan</b>${pill('Free')}</div><span class="dim">Pricing isn't set yet. [PLAN DETAILS]</span></div>`));
  reg('prefs-about', 'Settings', 'About', () => pref('about', 'About', `<div class="box col"><div class="between"><b>Flux</b><span class="mono">0.1.0 build 1</span></div><div class="row">${btn('Check for updates')}${btn('Copy version info', { k: 'g' })}</div></div><div class="lst box">${[['Attributions and licenses', 'legal-credits'], ['Privacy policy', 'legal'], ['Terms', 'legal-terms'], ['Create a diagnostic report', 'diag']].map(r => `<a href="#${r[1]}" data-go="${r[1]}" style="text-decoration:none"><div class="ti"><b>${r[0]}</b></div>${ic('exp', 15)}</a>`).join('')}</div>`));

