  const helpShell = (on, title, body) => `<div class="app notp">${topbar('Help', 'Works offline', btn('Close', { k: 'g', go: 'home' }))}${rail(HOME, 'help')}<main class="main" id="m"><div class="tabs">${[['help', 'Guides'], ['trouble', 'Troubleshooting'], ['legal', 'Privacy'], ['legal-terms', 'Terms'], ['legal-credits', 'Attributions']].map(t => `<a href="#${t[0]}" data-go="${t[0]}" class="${t[0] === on ? 'on' : ''}">${t[1]}</a>`).join('')}</div><div class="pg in"><h1 class="h1">${title}</h1>${body}</div></main></div>`;
  reg('help', 'Help', 'Guides', () => helpShell('help', 'How can we help?', `${inp('', 'Search help')}<div class="g3">${[['Your first 8D track', '90 seconds'], ['Edit by deleting words', '3 minutes'], ['Clean up a noisy recording', '4 minutes'], ['Splitting stems', '2 minutes'], ['Understanding LUFS', '5 minutes'], ['Drawing paths on the stage', '3 minutes'], ['Backing up your projects', '2 minutes'], ['Keyboard-only editing', '6 minutes'], ['Preset file format', 'For developers']].map(g => tile('', g[0], g[1], '')).join('')}</div>`));
  reg('trouble', 'Help', 'Troubleshooting', () => helpShell('trouble', 'Something wrong?', `<div class="lst box">${[['I hear nothing', 'Check the output device and that this tab is not muted. Press Play once: browsers need a click before they make sound.'], ['Clicks or dropouts while playing', 'Set Quality to Balanced in Settings, under Audio. Close other heavy tabs.'], ['8D sounds flat or inside my head', 'Run the headphone check, then try another head shape. Add some room. It will not work on speakers.'], ['Stems are slow', 'Your browser may not have WebGPU. Use Fast mode, or try Chrome or Edge.'], ['My AAC export option is missing', 'Your browser has no AAC encoder. Use Chrome or Edge, or export FLAC or Opus.'], ['Project won\'t open', 'Flux keeps earlier snapshots. Open History, or restore from your .flux backup.']].map(r => `<div style="align-items:flex-start;flex-direction:column;gap:3px"><b class="h3">${r[0]}</b><span class="dim">${r[1]}</span></div>`).join('')}</div><div class="row">${btn('Create a diagnostic report', { i: 'bug', go: 'diag' })}</div>`));
  reg('diag', 'Help', 'Diagnostic report', () => dlg('trouble', 'Diagnostic report', `<p class="dim">Creates a small file you can send with a support request. You decide whether to send it.</p><div class="lst">${[['Included', 'Browser, device, Flux version, error log, glitch counts', 'ok'], ['Never included', 'Audio, transcripts, project names, file names', 'bad']].map(r => `<div style="align-items:flex-start"><div class="ti"><b class="${r[2]}">${r[0]}</b><span style="white-space:normal">${r[1]}</span></div></div>`).join('')}</div>`, `${btn('Cancel', { k: 'g', go: 'trouble' })}${btn('Save report', { k: 'p', i: 'exp', go: 'trouble' })}`));
  const legalP = `<div class="legal"><p>[DRAFT: needs legal review before launch.] This page is laid out for the final text.</p><h3>What stays on your device</h3><p>Your audio, projects, transcripts and AI results are stored and processed on your device.</p><h3>What leaves your device</h3><p>Nothing, unless you turn on a cloud feature for a specific job. Cloud audio is encrypted in transit and deleted within 24 hours.</p><h3>Your rights</h3><p>You can delete all cloud data from Settings at any time.</p></div>`;
  reg('legal', 'Help', 'Privacy policy', () => helpShell('legal', 'Privacy', legalP));
